INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e4a69e88-63e8-4cf8-ab52-555d926581a8', '01e79977-9e57-4806-881a-cceb7f4be5bf', 'A', 'Plain Lidocaine 1% without Adrenaline (Epinephrine)', 1, 'Correct. Infiltration of local anaesthetic with adrenaline (vasoconstrictor) into end-artery regions (fingers, toes, nose, ear, penis) carries high risk of severe ischaemia and gangrenous tissue necrosis.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a52ce70e-c44a-490d-8281-53e4570cf117', '01e79977-9e57-4806-881a-cceb7f4be5bf', 'B', 'Lidocaine 2% with Adrenaline 1:80,000 solution', 0, 'Contraindicated and dangerous for digital ring block due to end-arteriole vasospasm.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4f6213f8-4817-47b8-b1a0-2a92446be45c', '01e79977-9e57-4806-881a-cceb7f4be5bf', 'C', 'Bupivacaine 0.5% with Adrenaline 1:200,000 for rapid local digital infiltration', 0, 'Strictly contraindicated for end-artery infiltration.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('fb8d7823-e788-4cf5-a593-2d80d1533d35', '01e79977-9e57-4806-881a-cceb7f4be5bf', 'D', 'Cocaine hydrochloride topical paste', 0, 'Deprecated toxic practice for peripheral skin suturing.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ee0c4e03-eded-4b2d-8176-3a95b2a51099', '01e79977-9e57-4806-881a-cceb7f4be5bf', 'E', 'Inject exceeding maximum plain lidocaine safe limit of 3 mg/kg (or 200 mg total)', 0, 'Dose violation leading to central nervous system and cardiovascular toxicity.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('e6353a4e-7e10-4411-97bb-c11bd9e51f36', '01e79977-9e57-4806-881a-cceb7f4be5bf', 'Never use adrenaline-containing local anaesthetics in areas with end-artery circulation (digits, ear, nose, penis).', 'Intralipid (20% lipid emulsion) is the specific rescue agent for systemic local anaesthetic toxicity (LAST). Reference: BNF Section 15.2 & Resuscitation Council UK.', 'BNF Section 15.2 & Resuscitation Council UK', 1789734485, 1789734485);
