INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('404a24e7-df2a-45f6-9480-e81b0735f007', 'ACP-Q-1866', 1, 'published', 'p-mpharm', 'sub-paracetamol-tox', 'hard', 'sba', 'gp', 'human', 1789734485, 1789734485, 1789734485);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('82dfe57f-3c59-4594-9d36-8433b2ff3309', '404a24e7-df2a-45f6-9480-e81b0735f007', 'A 24-year-old patient reports ingesting 20 g of paracetamol in divided doses over the past 14 hours ("staggered overdose"). Baseline blood tests show normal ALT and normal creatinine. (Case Ref: POISONING-EMERGENCY-1866). Relevant physiological and medication history have been reviewed.', 'What is the mandatory clinical treatment decision regarding Acetylcysteine?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f7e8f6e2-0895-407c-a8e4-d9c7c86492c8', '404a24e7-df2a-45f6-9480-e81b0735f007', 'A', 'Initiate IV Acetylcysteine immediately without waiting for serum paracetamol levels or nomogram plotting', 1, 'Correct. In staggered paracetamol overdoses (taken over > 1 hour), the paracetamol treatment nomogram CANNOT be used. Acetylcysteine must be commenced immediately regardless of the serum paracetamol concentration.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1a23304d-94dc-44eb-ab35-959495562827', '404a24e7-df2a-45f6-9480-e81b0735f007', 'B', 'Wait for the 4-hour serum paracetamol level and plot on the single-ingestion nomogram curve', 0, 'Fatal error. The nomogram is validated ONLY for acute single ingestions within 4-15 hours. Staggered overdoses render the nomogram uninterpretable.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('057bc537-ae6e-45ef-8dca-90b2eb46f729', '404a24e7-df2a-45f6-9480-e81b0735f007', 'C', 'Administer Oral Activated Charcoal 50 g at 14 hours post-ingestion', 0, 'Ineffective and contraindicated. Activated charcoal is only effective within 1 hour of ingestion and impairs oral antidotes.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c52c78ce-5c5a-42ea-85eb-34d90813e7a8', '404a24e7-df2a-45f6-9480-e81b0735f007', 'D', 'Withhold acetylcysteine because baseline transaminases (ALT) are currently normal', 0, 'Fatal error. ALT rises 24-48 hours after ingestion; waiting for hepatotoxicity before treating causes irreversible liver failure.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d535a90e-4151-448a-8e21-2e4058722ec6', '404a24e7-df2a-45f6-9480-e81b0735f007', 'E', 'Stop acetylcysteine infusion immediately if mild flush develops without anaphylactoid assessment', 0, 'Incorrect management. Common non-IgE mediated reactions can be managed by pausing infusion, giving antihistamine, and restarting at slower rate.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('9e42d31d-165a-4cf9-8d72-e6dba6dc913d', '404a24e7-df2a-45f6-9480-e81b0735f007', 'Never use the paracetamol nomogram for staggered overdoses. Start Acetylcysteine immediately.', 'Snap 12-hour or simplified 2-bag IV acetylcysteine regimens reduce adverse hypersensitivity reactions. Reference: TOXBASE & MHRA Drug Safety Update: Acetylcysteine for paracetamol overdose.', 'TOXBASE & MHRA Drug Safety Update: Acetylcysteine for paracetamol overdose', 1789734485, 1789734485);
